    ('9b3b5b01-3c19-54c9-b88a-34c8209e6c53', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Приветствие', 'На вход подаётся одна строка с именем без пробельных символов по краям. Выведите «Привет, <имя>!». Сохраните пробелы внутри имени.', TRUE, 'PRACTICAL',
     $json$ {"JAVA": "import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        String name = input.nextLine();\n        // Выведите приветствие.\n    }\n}\n"}$json$::jsonb, $json$[{"stdin": "Анна\n", "expectedOutput": "Привет, Анна!"}, {"stdin": "Java Developer\n", "expectedOutput": "Привет, Java Developer!"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('fe4de5c5-a19f-5256-b5f8-3be816cf8936', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Инструменты JDK', 'Какой инструмент компилирует файл Main.java в байт-код?', TRUE, 'QUIZ',
