    ('5ec75962-a293-5d32-b0ad-935f822bb2c0', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Минимум и максимум', 'Считайте n (1 ≤ n ≤ 1000) и n целых чисел от −1000000 до 1000000. Выведите минимальное и максимальное числа через пробел.', TRUE, 'PRACTICAL',
     $json$ {"JAVA": "import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        int count = input.nextInt();\n        // Считайте числа и выведите границы.\n    }\n}\n"}$json$::jsonb, $json$[{"stdin": "5\n3 -4 10 8 1\n", "expectedOutput": "-4 10"}, {"stdin": "1\n-7\n", "expectedOutput": "-7 -7"}, {"stdin": "4\n-9 -2 -4 -2\n", "expectedOutput": "-9 -2"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('286c9de5-2592-5d9f-9031-46f5512fe8e6', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Целочисленные операции', 'Выберите все верные утверждения для выражений Java с целочисленными литералами.', TRUE, 'QUIZ',
     NULL, NULL, NULL, NULL, $json$[{"id": "a", "text": "Результат 7 / 2 равен 3."}, {"id": "b", "text": "Результат 7 % 2 равен 0."}, {"id": "c", "text": "Результат 7 / 2.0 равен 3.5."}, {"id": "d", "text": "Значение 7 / 2 автоматически округляется до 4."}]$json$::jsonb, $json$["a", "c"]$json$::jsonb),
    ('1baedff4-d86f-5933-8a01-b4778ef6b109', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Класс прямоугольника', 'Считайте целые ширину и высоту (от 1 до 10000). Реализуйте класс Rectangle с методами area и perimeter. Выведите площадь и периметр через пробел.', TRUE, 'PRACTICAL',
     $json$ {"JAVA": "import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        Rectangle rectangle = new Rectangle(input.nextInt(), input.nextInt());\n        System.out.println(rectangle.area() + \" \" + rectangle.perimeter());\n    }\n\n    static class Rectangle {\n        Rectangle(int width, int height) {\n            // Сохраните размеры в полях.\n        }\n\n        int area() {\n            return 0;\n        }\n\n        int perimeter() {\n            return 0;\n        }\n    }\n}\n"}$json$::jsonb, $json$[{"stdin": "4 7\n", "expectedOutput": "28 22"}, {"stdin": "1 1\n", "expectedOutput": "1 4"}, {"stdin": "10000 2\n", "expectedOutput": "20000 20004"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('e9c81a76-0813-508e-9ed2-04fd80379040', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Передача аргументов', 'Метод получает параметр StringBuilder. Что может увидеть вызывающий код после завершения метода?', TRUE, 'QUIZ',
     NULL, NULL, NULL, NULL, $json$[{"id": "a", "text": "Добавление текста через append к переданному объекту."}, {"id": "b", "text": "Замену значения своей переменной, если параметру метода присвоили новый объект."}, {"id": "c", "text": "Автоматическое копирование переданного объекта."}, {"id": "d", "text": "Изменение типа своей переменной."}]$json$::jsonb, $json$["a"]$json$::jsonb),
    ('331d9819-364f-5804-a4dd-fa520a58e7dd', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Стоимость доставки', 'Считайте вид доставки STANDARD или EXPRESS и массу целым числом от 1 до 1000 кг. Обычная доставка стоит 100 + 20 × масса, срочная — 200 + 35 × масса. Реализуйте оба тарифа через интерфейс Delivery и выведите стоимость выбранного тарифа.', TRUE, 'PRACTICAL',
     $json$ {"JAVA": "import java.util.Scanner;\n\npublic class Main {\n    interface Delivery {\n        int cost(int weight);\n    }\n\n    static class StandardDelivery implements Delivery {\n        public int cost(int weight) {\n            return 0;\n        }\n    }\n\n    static class ExpressDelivery implements Delivery {\n        public int cost(int weight) {\n            return 0;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        String type = input.next();\n        int weight = input.nextInt();\n        // Выберите тариф и выведите его стоимость.\n    }\n}\n"}$json$::jsonb, $json$[{"stdin": "STANDARD 3\n", "expectedOutput": "160"}, {"stdin": "EXPRESS 3\n", "expectedOutput": "305"}, {"stdin": "EXPRESS 1\n", "expectedOutput": "235"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('e9ed31e7-f91d-5f40-9fb8-8447f3234e72', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Равенство объектов', 'Какие условия входят в контракт equals и hashCode? Выберите все верные варианты.', TRUE, 'QUIZ',
     NULL, NULL, NULL, NULL, $json$[{"id": "a", "text": "Объект равен самому себе."}, {"id": "b", "text": "Два равных объекта возвращают одинаковый hashCode."}, {"id": "c", "text": "Одинаковый hashCode гарантирует равенство."}, {"id": "d", "text": "Если a.equals(b) возвращает true, то b.equals(a) возвращает true."}]$json$::jsonb, $json$["a", "b", "d"]$json$::jsonb),
    ('e1806705-22cd-5d38-b418-1a6bbdf19e6a', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Безопасное деление', 'Считайте два целых числа от −1000000 до 1000000. Выведите результат целочисленного деления первого на второе. Перехватите ArithmeticException при делении на ноль и выведите ERROR.', TRUE, 'PRACTICAL',
     $json$ {"JAVA": "import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        int dividend = input.nextInt();\n        int divisor = input.nextInt();\n        // Выполните деление и обработайте исключение.\n    }\n}\n"}$json$::jsonb, $json$[{"stdin": "7 2\n", "expectedOutput": "3"}, {"stdin": "-7 2\n", "expectedOutput": "-3"}, {"stdin": "5 0\n", "expectedOutput": "ERROR"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('96df0eba-06df-5fa5-ab69-2cc1817ef5ab', '39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'Обработка исключений', 'Как обработать ожидаемую ошибку Integer.parseInt при преобразовании пользовательского ввода?', TRUE, 'QUIZ',
